  "headline": "Meropenem is not on FDA's shortage list as of 2026-10-21; Corvale Lakeside has 11.2 days on hand while other sites hold 22.3 and 27.9 days",
  "headline_cites": ["D4", "D1", "D2", "D3"],
  "sentences": [
    {
      "text": "FDA's drug shortage list does not include meropenem as of 2026-10-21.",
      "cites": ["D4"]
    },
    {
      "text": "Corvale East holds 337 vials of the 1 g/30 mL presentation with 15.1 vials used per day, giving 22.3 days on hand.",
      "cites": ["D1"]
    },
    {
      "text": "Corvale General holds 425 vials at 15.2 vials per day, giving 27.9 days on hand.",
      "cites": ["D2"]
    },
    {
      "text": "Corvale Lakeside holds 29 vials at 2.6 vials per day, giving 11.2 days on hand.",
      "cites": ["D3"]
    },
    {
      "text": "The top-ranked purchasing option is Gland Pharma Limited, whose plant was last inspected VAI on 2023-06-27.",
      "cites": ["D5"]
    },
    {
      "text": "Secondary options include WG Critical Care, LLC and ARMAS PHARMACEUTICALS INC, the latter supplied by Brooks Steriscience Limited last inspected VAI on 2024-11-12.",
      "cites": ["D6", "D7"]
    }
  ]
}
